    private val cache = java.util.concurrent.ConcurrentHashMap<String, Char>()

    /** 取分组名首字母；中文按拼音，英文按大写，其它归到 #。 */
    fun initial(name: String): Char {
        val text = name.trim()
        if (text.isEmpty()) return '#'
        cache[text]?.let { return it }
        val first = text[0]
        val result = when {
            first in 'A'..'Z' -> first
            first in 'a'..'z' -> first.uppercaseChar()
            first.code in HAN_START..(HAN_START + HAN_INITIALS.length - 1) ->
                HAN_INITIALS[first.code - HAN_START]
            else -> '#'
        }
        cache[text] = result
        return result
    }

    /** 分组排序：先按首字母 A–Z（# 最后），同字母内按名称排序。 */
    fun sortKey(name: String): String {
        val letter = initial(name)
        // '#'（日文/符号等无首字母）统一排到最后；其余按 A–Z。
        val prefix = if (letter == '#') "\uFFFF" else letter.toString()
        return prefix + name.lowercase(Locale.ROOT)
    }
}
